function validate([n, cost]) {
  if (!Number.isInteger(n) || n < 3 || n > 100000) return 'n is a whole number from 3 to 10^5.';
  if ((n + 1) & n) return 'n + 1 must be a power of 2, so the tree is perfect.';
  if (!Array.isArray(cost) || cost.length !== n) return 'cost needs exactly n values.';
  if (!cost.every(v => Number.isInteger(v) && v >= 1 && v <= 10000)) return 'Each cost is a whole number from 1 to 10^4.';
  return null;
}

