function minIncrements(n, cost) {
  // path[i] becomes the heaviest path cost from node i + 1 down to a leaf.
  const path = [...cost];
  let increments = 0;
  for (let parent = Math.floor(n / 2); parent >= 1; parent--) {
    const left = path[2 * parent - 1];
    const right = path[2 * parent];
    increments += Math.abs(left - right);
    path[parent - 1] += Math.max(left, right);
  }
  return increments;
}

