function minIncrements(n, cost) {
  // Top-down: every subtree must reach exactly the cost its heaviest path already has,
  // and the slack is added as high up as possible, on the subtree's own root.
  const heaviest = v => (v > n ? 0 : cost[v - 1] + Math.max(heaviest(2 * v), heaviest(2 * v + 1)));
  const spend = (v, need) => {
    if (v > n) return 0;
    const raise = need - heaviest(v);
    const rest = need - raise - cost[v - 1];
    return raise + spend(2 * v, rest) + spend(2 * v + 1, rest);
  };
  return spend(1, heaviest(1));
}

