function generate(rand, size) {
  const depth = size === 'large' ? 10 : 2 + Math.floor(rand() * 3);
  const n = 2 ** depth - 1;
  const top = size === 'large' ? 10000 : [1, 3, 10, 10000][Math.floor(rand() * 4)];
  return [n, Array.from({ length: n }, () => 1 + Math.floor(rand() * top))];
}
